REVOKE ALL ON FUNCTION public.assessment_guard(),public.detect_goal_candidates(),public.handle_new_user(),public.new_lead_notification(),public.on_training_finished(),public.on_version_created(),public.sync_assessment_birth() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.create_workout_revision(uuid),public.has_photo_consent(uuid),public.has_role(uuid,public.app_role),public.is_own_student(uuid),public.is_trainer_of(uuid),public.link_trainer(text),public.refund_payment(uuid,text),public.register_payment(uuid,numeric,date,text,text,text),public.restricted_student_access(uuid),public.review_workout_version(uuid,text,text),public.set_consents(boolean,boolean),public.set_manual_block(uuid,boolean,text),public.training_open_for_me(uuid),public.upsert_plan(uuid,numeric,date,date,date,public.plan_periodicity,integer,boolean),public.version_editable_by_trainer(uuid),public.version_trainer_can_read(uuid),public.version_visible_to_student(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_workout_revision(uuid),public.has_photo_consent(uuid),public.has_role(uuid,public.app_role),public.is_own_student(uuid),public.is_trainer_of(uuid),public.link_trainer(text),public.refund_payment(uuid,text),public.register_payment(uuid,numeric,date,text,text,text),public.restricted_student_access(uuid),public.review_workout_version(uuid,text,text),public.set_consents(boolean,boolean),public.set_manual_block(uuid,boolean,text),public.training_open_for_me(uuid),public.upsert_plan(uuid,numeric,date,date,date,public.plan_periodicity,integer,boolean),public.version_editable_by_trainer(uuid),public.version_trainer_can_read(uuid),public.version_visible_to_student(uuid) TO authenticated,service_role;
ALTER FUNCTION public.period_interval(public.plan_periodicity) SET search_path=public;
ALTER FUNCTION public.safe_uuid(text) SET search_path=public;
ALTER FUNCTION public.today_br() SET search_path=public;
CREATE OR REPLACE FUNCTION public.new_student_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.trainer_id IS NOT NULL THEN PERFORM public.notify(NEW.trainer_id,'Novo cadastro de aluno','Um aluno se vinculou ao seu acompanhamento.','/admin/alunos/'||NEW.id,'new_student_'||NEW.id);END IF;RETURN NEW;END $$;
CREATE TRIGGER student_created_notification AFTER INSERT OR UPDATE OF trainer_id ON public.students FOR EACH ROW EXECUTE FUNCTION public.new_student_notification();
REVOKE ALL ON FUNCTION public.new_student_notification() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.profile_input_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(NEW.full_name)>150 OR length(NEW.phone)>30 OR NEW.birth_date>public.today_br() THEN RAISE EXCEPTION 'Dados pessoais inválidos';END IF;IF TG_OP='INSERT' THEN NEW.phone:=coalesce((SELECT raw_user_meta_data->>'phone' FROM auth.users WHERE id=NEW.id),NEW.phone,'');END IF;RETURN NEW;END $$;
CREATE TRIGGER profile_input_validation BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.profile_input_guard();
CREATE OR REPLACE FUNCTION public.assessment_consent_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF public.is_own_student(NEW.student_id) AND NOT EXISTS(SELECT 1 FROM public.students WHERE id=NEW.student_id AND data_consent_at IS NOT NULL) THEN RAISE EXCEPTION 'Autorize o uso dos dados antes de salvar a avaliação';END IF;IF length(NEW.full_name)>150 OR NEW.weight_kg<=0 OR NEW.weight_kg>600 OR NEW.height_cm<=0 OR NEW.height_cm>300 OR NEW.birth_date>public.today_br() THEN RAISE EXCEPTION 'Dados da avaliação inválidos';END IF;RETURN NEW;END $$;
CREATE TRIGGER assessment_consent_validation BEFORE INSERT OR UPDATE ON public.assessments FOR EACH ROW EXECUTE FUNCTION public.assessment_consent_guard();
CREATE OR REPLACE FUNCTION public.video_url_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.video_url IS NOT NULL AND NEW.video_url<>'' AND (NEW.video_url !~ '^https://' OR length(NEW.video_url)>2000) THEN RAISE EXCEPTION 'Use um link https válido para o vídeo';END IF;RETURN NEW;END $$;
CREATE TRIGGER workout_video_validation BEFORE INSERT OR UPDATE ON public.workout_exercises FOR EACH ROW EXECUTE FUNCTION public.video_url_guard();